INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yuoni-sunset-edition', 171858, '2021-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co493g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar19yk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuoni: Sunset Edition', 'Yuoni is a first-person narrative horror game that whisks you away to a sunset-stained world to play a deadly game of hide and seek. As grade-schooler Ai, navigate authentic Japanese environments and utilise every hiding space you can find to survive the horrors ahead. And if they find you… run.' FROM games WHERE igdb_id = 171858 ON CONFLICT (game_id, language_code) DO NOTHING;
