INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shores Unknown', 'A turn-based tactical RPG rendered in a rich, low-poly aesthetic. Build your own team of mercenaries, forge alliances, wage battles, and journey beyond the seething wall of fog known only as the Murk in this decision-influenced, narrative-driven adventure. What dangers await you on Shores Unknown?' FROM games WHERE igdb_id = 116689 ON CONFLICT (game_id, language_code) DO NOTHING;
