INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('seal-electric-railway', 147668, '2021-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dki.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arat1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seal Electric Railway', 'The life of a curly, chewy seal is being targeted by a vicious orca! Drive the train back to the station safely to prevent the seals from falling into the sea. Let''s get going! • How to play You are the "seal" of a train driver on the ocean. The train is easily affected by waves, so it is important to keep the car balanced. When you tilt the Joy-Con back and forth and left and right, the train will tilt in tandem. To prevent the seals on the ceiling of the train from falling into the sea balance your vehicles and drive safely. Orcas from rival railroads patrol the seas and attack your train with terrifying attacks. It is your mission to protect your passengers from the orcas and get them safely to the station. Bring as many passengers as possible to the station during your working hours to meet your quota! With the share of the Joy-Con, you can play cooperatively with two players on one Nintendo Switch.' FROM games WHERE igdb_id = 147668 ON CONFLICT (game_id, language_code) DO NOTHING;
