INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coronation', 'Coronation is an online open-world medieval multiplayer game developed by Twin Sword Studio with the help of lovely Patreons and a closely-knitted Discord community. Design fortified castles to withstand attacks from AI or players, keep its people happy, well-fed and rested, or even decorate it to impress curators and provide beautiful homes for accommodation. It is inspired by Mount & Blade Bannerlord, Rust, Sims 3/4, Runescape, Anno 1404 and Tropico 6.' FROM games WHERE igdb_id = 91381 ON CONFLICT (game_id, language_code) DO NOTHING;
