INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undead Battle Royale', 'An extensive arsenal of weapons and a thirst for zombie blood are all that stand between you and a grisly demise in the pick-up-and-play action of Undead Battle Royale! The undead have risen. Civilisation has fallen. Now only one person can bring humanity back from the brink: you! Survive the onslaught, slaughter your foes, and seize victory!' FROM games WHERE igdb_id = 148320 ON CONFLICT (game_id, language_code) DO NOTHING;
