INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweets Swap', 'Sweets Swap is a classic three match game where you need to match three of the same kind to advance to the next level. Simple enough and flavoured with sweet variations to keep you on your toes! Features : - Simple three match game - Many variations and different objectives to reach - Colorful and sweet art style - 100 Levels to complete' FROM games WHERE igdb_id = 147097 ON CONFLICT (game_id, language_code) DO NOTHING;
