INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('top-gun-air-combat', 147123, '2021-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59dw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9oz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun Air Combat', 'Nato armies are engaged in a 21th century conflict against Russian Federation Army. As a Top Gun Pilot from US Air Force, you fly the best American Fighters (F18, F35, F22...) through multiple missions across battlefields around the world (Cuba, Lebanon, Ukraine...) in cooperation with your European Allies Aircrafts (Typhoon, Rafale, Mirage...). You will be engaged in air combat against Russian Fighters (Mig 27, Mig 33, Su 37...). Lock your targets, choose amongst different missile systems and riffle, shoot and forget! Powered by a very realistic physic engine that makes the game highly playable, Top Gun Air Combat will make you feel real sensations of modern air combat.' FROM games WHERE igdb_id = 147123 ON CONFLICT (game_id, language_code) DO NOTHING;
