INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('throw-it-animal-park', 147497, '2021-04-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59c0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9s3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Throw it! Animal Park', '(Throw it! Animal Park) is an animal dropping game that anyone can enjoy. Fly the animals and drop them into the receptacle, and the animals will come to the park! When you hit the same animal, it gets bigger and bigger and you get a high score! When you see the biggest animal in the map, you''ll see...! When you get an item from the roulette wheel, various effects will occur. You''ll be lucky if you get a fever! You can litter all you want for 10 seconds! There''s also a gold buffalo that makes lots of animals fall, a silver buffalo that shakes the table, and lots of other fun stuff! In addition, new animals will appear from the rainbow-colored eggs! Let''s get all 32 types of animals to come to the park! (Throw it! Animal Park) can be enjoyed in four different modes. "One Player with no time limit" There is no time limit! There is no time limit! "One Player with time limit" How many points can you get in a short time? "Two Player with time limit" With family! With friends! Let''s aim for a high score together! "Animal Park" After playing, let''s take a look at the park. The animals I got are coming to the park. Touch the touch screen or press a button to enjoy the reaction of cute animals. In the picture book, you can see the animals that have grown one by one.' FROM games WHERE igdb_id = 147497 ON CONFLICT (game_id, language_code) DO NOTHING;
