INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burger-master', 147581, '2021-02-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co576x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9yq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burger Master', 'Burger Master is a fun game where you need to create the best burger joint in town. In order to do that, you must do your best and bring in the best skills you have to fulfill the needs of your clients. This is an intense, fun and exciting game that constantly tests your cooking skills. There are 3 worlds in the game, with 60 different levels in each world. That gives plenty of opportunities to test out your experience and push it to the next level. As you play, you can use one of the 3 power-ups like Customer Happy Time, Coin Magnet and Automatic Hinting. All of these play a great role as you try to become better and better. There are 21 customer types, each one with their own unique requirements. You can even unlock ingredients, power-ups and characters as you go along. If you love great cooking games, try out Burger Master today and have fun preparing some amazing burgers!' FROM games WHERE igdb_id = 147581 ON CONFLICT (game_id, language_code) DO NOTHING;
