INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slow Living With Princess', 'Slow Living With Princesss is an RPG adventure game. Gideon Ragnason has been discharged from the Hero''s party because he was not "strong enough". Since then, he has retired from the front lines of the battle and changed his name to Red. Now he opens an apothecary in the frontier called Zoltan and hopes to have a happy slow living life style.' FROM games WHERE igdb_id = 172447 ON CONFLICT (game_id, language_code) DO NOTHING;
