INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noara: The Conspiracy', 'Noara: The Conspiracy is a 3D strategy game based on the universe of Noara. At the head of an army where each unit has its own set of skills, the aim of the game is to destroy the opponent''s stronghold in order to win the battle. It revisits the turn-based strategy game by combining it with the dynamism of real-time games and the reflection of chess games. From a brand new genre, Noara is a Multiplayer Online Chess Arena (MOCA) with a unique gameplay.' FROM games WHERE igdb_id = 178357 ON CONFLICT (game_id, language_code) DO NOTHING;
