INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('g-mode-archives-29-zanac', 147145, '2021-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5awd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb7j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G-Mode Archives 29: Zanac', 'Zanac is a classic shooting game that made a name for itself in the gaming industry in 1986. This mobile app version of the game recreates the original game, including hidden elements. The game system has been rearranged to make it easier to play. In addition, this title has been improved with the G-Mode archives. The "Arrange" mode allows you to fly through the air more intensely and smoothly. The game includes two modes: "Arrange" mode, which is more intense and smoother, and "Original" mode, where you can enjoy the nostalgic graphics of the time. There are eight types of special weapons. Each weapon has its own unique characteristics, and the power of each weapon increases with successive attacks. The thrill comes from the large number of bullets that the enemy attacks with. Use the special attacks to your advantage to defeat the final boss!' FROM games WHERE igdb_id = 147145 ON CONFLICT (game_id, language_code) DO NOTHING;
