INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crab Game', 'Crab Game is a First-Person Multiplayer game where you fight for the ultimate cash price in different minigames based on children''s games, until only one player is left to claim it all. Definitely not based on any online streaming pop culture korean tv shows, as that would get me in legal trouble, so we''re certainly not doing that.' FROM games WHERE igdb_id = 178351 ON CONFLICT (game_id, language_code) DO NOTHING;
