INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faded Memories: Video Game Edition', 'Faded Memories is an exciting, 2D action-adventure game. It has the spice of a rogue-like, the options of a sandbox, and the brain flexing moments that come from good trivia. Use these mechanics to embark on a magical journey to save your sister, your mother, and the whole Mouse Kingdom.' FROM games WHERE igdb_id = 393365 ON CONFLICT (game_id, language_code) DO NOTHING;
