INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('find-10-differences', 150261, '2021-06-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4dav.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc7j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Find 10 Differences', 'Find the differences games can be very interesting for everyone, especially kids! In this game, there are 25 levels in total. In each level, you see two versions of an image and you have to find the 10 differences between them . There is also a timer that your final score is based on it (the highest is 3 stars). Note that wrong differences will also reduce your time and final score, so think carefully before deciding! All the games images are cute and cartoon images of animals, robots, monsters and cartoons which make the game even more interesting for kids!' FROM games WHERE igdb_id = 150261 ON CONFLICT (game_id, language_code) DO NOTHING;
