INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cube Blast: Match', 'Cube Blast will challenge even the most reputable puzzle solvers with a mind bending 3D twist on the classic color blast formula. Push your spatial thinking abilities to their limits, as you solve increasingly complex puzzles on a 3D tower of colorful blocks, with new and exciting mechanical twists popping up, just when you thought you saw all the game has to offer. If you are not yet convinced: there are also aliens, and explosions!' FROM games WHERE igdb_id = 152613 ON CONFLICT (game_id, language_code) DO NOTHING;
