INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jigsaw-masterpieces-ex-kawaii-cute-goddesses', 173123, '2021-09-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co599o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1501.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jigsaw Masterpieces EX: Kawaii Cute Goddesses', '"Jigsaw Masterpieces" series is a digital jigsaw puzzle game that is easy for anyone to play. Many convenient functions for completing the puzzle, such as the function to separate edge and inner pieces and the auto save function for playing lighthearted at any time. "Jigsaw Masterpieces EX - Kawaii Cute Goddesses -" contains a total of 120 images of 24 cute girls based on mythical goddesses. Each puzzle has three different numbers of pieces, so you can have a lot of fun. There are 70 pieces for everyone, 260 pieces for a bit of challenge, and 400 pieces for the professional level. Which game level do you want to play first? If it is a digital jigsaw puzzle... You don''t have to worry about losing the pieces. You don''t have to need prepare a large space to suspend the puzzle. Let''s have fun playing the jigsaw puzzle with "Jigsaw Masterpieces"!' FROM games WHERE igdb_id = 173123 ON CONFLICT (game_id, language_code) DO NOTHING;
