INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clockwork Aquario', 'Clockwork Aquario was the last arcade game ever developed by the legendary Westone Bit Entertainment in 1992, but was never finished. The game was thought to be lost in time, but Strictly Limited Games set out on the mission to dig deep into video game archeology and save Clockwork Aquario from being lost in time.
