INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcade-space-shooter-2-in-1', 152522, '2021-06-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co570p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcpt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Space Shooter 2 in 1', 'In Space War Infinity, evolve your ship as you advance and level up in the game. Unlock more than 20 different upgrades and weapons during the game. Defeat 5 bosses ready to spray you. Endless game! After completing all the missions, try to move up in rank by facing waves of enemies created in real time. In Space Smash, avoid being crushed by the space storm by collecting Orbs of blue energy to save more time and space, watch out for the red Orbs. Get the highest score possible! Get to the podium on the scoreboard and try to stay there as long as possible. Unlock ships with unique characteristics by collecting coins that appear in the arena.' FROM games WHERE igdb_id = 152522 ON CONFLICT (game_id, language_code) DO NOTHING;
