INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('racing-xtreme-2', 154989, '2021-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g8d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvgz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Racing Xtreme 2', 'Get into your Monster Truck, fasten your seat belt and be ready for a rough ride. Let the fire blaze merrily, race the fastest 4x4 offroad monster vehicles, and feast your eyes with the fast jump-filled racing on the beautiful, hills & valleys packed American countryside! Are you able to tame this beast? Jump behind the wheel of one of the 30 extremely powerful MONSTER TRUCKS and prove your skills in hardcore challenges! Choose between Limited Races, Extreme Races, Single Contest, and Daily Race mode and show the power of these beasts. Earn money and discover plenty of truck tuning options! Exchange your money on upgrades like new tires, nitrous, exhaust, engine, gears, booster, and body! Enjoy a perfectly designed 3D world with scenic valleys, hills, lakes, and railroads. Admire the amazing view, and keep your eyes on the road, rivals, and the closest ramp! Speed up, compete in drag racing, dash, conquer the hill, and uphill - the race is starting right now! Forget about casual arcade car racing, it''s time to try your skills on a real challenge. Race as fast as you can to become the top new monster truck driver in the world. Play now an extremely fast game with the amazing stunts and adrenaline!' FROM games WHERE igdb_id = 154989 ON CONFLICT (game_id, language_code) DO NOTHING;
