INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girls Tank Battle', 'The survival of girls who have fallen into a four-dimensional world begins. When you clear the stage, you select one of the three skills to challenge the next stage with your own strategy. ・ A tank battle that relieves stress with explosive direction begins. The exciting new-sense tank shooting game with simple manipulation! You can collect new military costumes of cute girls every five stages. Defeat the final boss and enjoy the images of all the girls in gallery mode.' FROM games WHERE igdb_id = 165605 ON CONFLICT (game_id, language_code) DO NOTHING;
