INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fiction.Colors', 'Endless subway rides, void probes, cosmic gardens and the fate of a planet, fiction.colors is a series of short atmospheric experiences to explore at leisure. A collection of places to explore, or ambient ''games,'' made from 2015 to 2022. Some are walking sims and others are fully passive. Take an endless train ride or roam sun-baked deserts. There''s plenty to see at your own pace.' FROM games WHERE igdb_id = 341152 ON CONFLICT (game_id, language_code) DO NOTHING;
