INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stardash', 147628, '2021-01-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5au2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arakw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stardash', 'Not just the looks of a classic game, also the gameplay of a classic platformer. This game is NOT EASY! you have an endless amount of lives, so you can quickly restart a level when you miss a jump, get hit by an enemy, get bitten by a plant, get hit by a spiky-ball, crushed by big statues, run onto spikes, get hit by a wasp, or any of the other many ways you''ll get stopped in your run. BUT when you do complete a level, the rush you get will keep you coming back for more, and more, and more, and.. Unlock special temple levels by finding hidden keys, unlock a flip-mode by completing a level both within the time set, and also by collecting all the coins in a level. Stardash is all about the gameplay thrown at you in awesome retro graphics and original chiptunes.' FROM games WHERE igdb_id = 147628 ON CONFLICT (game_id, language_code) DO NOTHING;
