INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vertical Shift', 'A VR Esport unlike any other. Fly through the arenas equipped with your Zenith Suit, an advanced movement system. Your Zenith Suit is equipped with Grapple Hooks, Jet Packs, and Gliders, giving you ultimate control over your flight.
