INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Natural Pressures', 'After a camping trip goes wrong, a terrific storm leaves you trapped in the forest! With minimal resources and a maze-like woodland to escape, you''d do anything to survive...even sacrifice your humanity! Will you keep grinding and fighting for a route home, or submit to the natural pressures and adapt to your new life?' FROM games WHERE igdb_id = 265670 ON CONFLICT (game_id, language_code) DO NOTHING;
