INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Hiking League DX', 'Who''s the best 2D platformer in the world? Find out in the League! Join Nelson in the Super Hiking League! An evil wizard is making the mountains disappear in a plan to make the world perfectly flat! As a member of the Super Hiking League you will not let this happen. Compete in climbing matches against other Hikers to collect all magic gems and stop his plans! Super Hiking League provides tight jump-rope-bend-swing-win gameplay with beautiful 8-bit+ graphics and a top notch authentic 8-bit soundtrack!' FROM games WHERE igdb_id = 163174 ON CONFLICT (game_id, language_code) DO NOTHING;
