INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Nations Game', 'World Nations Game is an online MMO game in which you can have your own virtual life. You can join a nation, buy vehicles, items, properties, open a political party, fight in international battlefields, participate in races, take part in special agent fights between agents from other countries, attack other citizens space colonies on any country map, be a nation senator or president, be part of the world congress, vote on nation issues and you can do many other activities.' FROM games WHERE igdb_id = 191282 ON CONFLICT (game_id, language_code) DO NOTHING;
