INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('funny-farm-animal-jigsaw-puzzle-game-for-kids-and-toddlers', 165619, '2021-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3rjy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11db.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Funny Farm Animal Jigsaw Puzzle Game for Kids and Toddlers', 'This animal puzzle game has been specially developed for children and includes different levels of difficulty that are freely adjustable. Furthermore, help functions can optionally be switched on, or the rotation for the puzzle pieces can be switched on. As soon as the rotation for the parts has been switched on, the parts can be rotated 90 degrees at a time. The puzzle game contains many great, funny and unique animal motifs suitable for children. Please note that this jigsaw puzzle game only supports touchscreen functionality. The menu and the scenes can only be played with the touch controls!' FROM games WHERE igdb_id = 165619 ON CONFLICT (game_id, language_code) DO NOTHING;
