INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Epic Adventure', 'Help your ninja buddie and his pals to go through 4 worlds and 36 levels in this side-scrolling arcade platformer game! Defeat monsters, collect coins and unlock weapons and new characters. Main Features: + 4 Worlds – 36 levels total, 4 Big Bosses fight at final level + Nice sound and graphics + Shop system, using free coins (gained through playing) to unlock new characters and collect items + Hit blocks to release random items + Special bullet range attack + addictive jump and run platform / obstacles runner + side-scroller gameplay with easy controls Enjoy!' FROM games WHERE igdb_id = 147458 ON CONFLICT (game_id, language_code) DO NOTHING;
