INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colors Live', 'Colors Live, the sequel to the critically acclaimed painting game Colors! 3D is finally coming to the Nintendo Switch along with a pressure sensitive Colors SonarPen included in every physical unit! Based on modern painting techniques originally developed for professional drawing tablets, Colors Live is tailored for the Nintendo Switch, and caters to everyone from serious artists to aimless doodlers. Whether you are looking to sketch, paint, or draw up your next plans for world domination, Colors Live is the perfect digital sketchbook.' FROM games WHERE igdb_id = 148019 ON CONFLICT (game_id, language_code) DO NOTHING;
