INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Together', 'Color the World together! Discover a new world, but do not do it alone - take a friend and play together! Travel together through increasingly demanding levels of difficulty in many interesting biomes. Color the world decolourised by the evil Mona Chrome! You will be accompanied by some popular and distinct heroes who can, but certainly do not, remind you of familiar characters. Our heroes are monophobes, so they must act together to get her!' FROM games WHERE igdb_id = 152248 ON CONFLICT (game_id, language_code) DO NOTHING;
