INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Mementos', 'When a man hasn’t returned from exploring an old abandoned house, his girlfriend decides to go to the house and find him. She’ll soon discover that the house has a story to tell, and it wants to show it to her through Super 8 Film. She now realizes that if she wants answers to what happened to her lover, she must watch the Super 8 Footage.' FROM games WHERE igdb_id = 372191 ON CONFLICT (game_id, language_code) DO NOTHING;
