INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tandem: A Tale of Shadows', 'Tandem: A Tale of Shadows redefines the puzzle platformer genre with a unique gameplay and exceptional aesthetics. Help Emma and the teddy bear Fenton solve the mystery of the disappearance of the famous magician Thomas Kane. Players will alternate between Emma’s top-down view and Fenton’s horizontal side-scroller view, using the former’s lantern to cast shadows the teddy bear can cross. In turn, the latter can activate switches that may be out of view.' FROM games WHERE igdb_id = 151134 ON CONFLICT (game_id, language_code) DO NOTHING;
