INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('glut-a-superabundance-of-nothing', 191500, '2021-09-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hid.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scfu08.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glut: A Superabundance of Nothing', 'GLUT (a superabundance of nothing), by Johanna Hedva, is an inquiry into the knowings and unknowings of embodiment. It is a sound work composed with divination and AI, which manifests as both an immersive physical installation and videogame. The core of GLUT is a sound composition made entirely of Hedva’s voice, ranging from its rawest expression of screams, to two AI vocal clones that, in order to trick the surveillance tactics embedded in AI, have been manipulated to sound ever more de-human.
