INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Svoboda 1945: Liberation', 'The horrors of World War II are over, but peace never came to the Czech village of Svoboda. You were sent to investigate a decades-old feud. Who can you trust to explain what happened? How was your family involved? Talk to witnesses to uncover the troubled past.
