INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin-chan: Me and the Professor on Summer Vacation - The Endless Seven-Day Journey', 'The Nohara family has decided to spend their summer vacation in Kumamoto. A week of life begins in the small town of Asso. Surrounded by abundant nature, you can catch rare insects, catch fish in nearby streams, and pick up wild plants. You can also record the fun events in a picture diary every day.' FROM games WHERE igdb_id = 143621 ON CONFLICT (game_id, language_code) DO NOTHING;
