INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Walking Dead: Survivors', 'Do you have what it takes to lead a community in the world of The Walking Dead? Can you overcome the never-ending threat of roaming Walkers as you scavenge for supplies across the ravaged Southern landscape? Cross paths with iconic Walking Dead heroes Rick, Michonne, and Glenn as you scour the radio waves searching for other survivors. Build a refuge from the rubble and defend it against overwhelming Walker herds – but be prepared to fight the living as well as the dead! Every action you take in this cutthroat world will come with a difficult choice: your humanity, or your survival?' FROM games WHERE igdb_id = 142749 ON CONFLICT (game_id, language_code) DO NOTHING;
