INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Songs for a Hero: Definitive Edition', 'Songs for a Hero is an old school sung-through video game extravaganza! Join an unlikely hero as he sings his way through a strange world full of floating platforms, bright and colorful enemies, and many other inexplicable phenomena in an adventure, unlike anything you have ever heard! This humorous old-school platformer features a fully dynamic soundtrack that reacts to your every input, meaning that the hero will always sing and crack jokes about whatever is happening to him, whenever it happens.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 154980 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
