INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Tower Defense', 'Prepare for intense and epic battles in this Tower Defense game with many different sceneries and toon characters. Upgrade your archers, enjoy magics, spells, super arrows and other power-ups, and defend your fortresses from barbarians. With its simple yet very addictive gameplay and its superb realization, Cartoon Tower Defense will offer you many hours of pure joy. Get Ready!' FROM games WHERE igdb_id = 186568 ON CONFLICT (game_id, language_code) DO NOTHING;
