INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoko & Yuki: Dr. Rat''s Revenge', 'Yoko & Yuki: Dr. Rat''s Revenge is a family game suitable for kids of all ages. Yoko and Yuki are two adorable cats in love with each other. But the devious doctor Rat stole Yuki from Yoko. Now it’s time to do some cat business, using helpful gadgets and solve puzzles in order to save your girlfriend. Our hero is equipped with scissors to cut ropes, gravitron to flip the world and spray can to find hidden objects. Daring players would be handsomely rewarded for using their wits and helping two cats to achieve their happiness!' FROM games WHERE igdb_id = 147271 ON CONFLICT (game_id, language_code) DO NOTHING;
