INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('car-wash-cars-and-trucks-garage-game-for-toddlers-and-kids', 158790, '2021-07-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co577v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxnv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Car Wash: Cars & Trucks Garage Game for Toddlers & Kids', 'Welcome to the world of car wash! In this amazing game for toddlers and kids of any age, you take care of washing and cleaning 25 different vehicles. Hose, brush, wipe, wax, dry, polish and even enchant the cars with a touch of magic to make them shine even brighter. No skill required. Just pick your tool and start swiping on the car to get the work done! Earn stars while working to unlock the remaining cars. Suitable for all car-enthusiast all over the world :) This game was designed and created with the help of kids and media-educators to ensure a relaxing, frustration free yet rewarding gaming experience for even the smallest kids. This game makes use of the touch screen functionality only. So the menu and every scene can be played with touch controls only.' FROM games WHERE igdb_id = 158790 ON CONFLICT (game_id, language_code) DO NOTHING;
