INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peppy''s Adventure', 'Peppy’s Adventure is a 1-screen, top-down, action-puzzle game controlled with directional inputs only. You control Peppy, a bun-shaped bunny, on his journey to rescue the village younglings from the clutches of the Hooded Fox. As you pursue his airship, you will have to solve your way through short challenging levels as fast as possible facing an army of reckless foxes.' FROM games WHERE igdb_id = 152303 ON CONFLICT (game_id, language_code) DO NOTHING;
