INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ayo the Clown', 'Ayo the Clown is a 2.5D side-scrolling platformer reminiscent of genre favorites like Mario and Donkey Kong. What sets Ayo the Clown apart from traditional platformers is its sense of adventure, light puzzle facets, and RPG elements.Like the Legend of Zelda series, Ayo’s potential isn’t realized at the game’s offset. You will collect skill upgrades and extra hearts that add to your overall life as you progress through this lush world.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 26755 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
