INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('comic-coloring-book-complete-edition', 186576, '2021-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57cv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c4s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Comic Coloring Book: Complete Edition', 'Many adventures await! Once upon a time, two children, a boy, and a girl found two unique toys - a robot and an alpacorn. These magically came to life to become our heroes'' best friends! Together they experience amazing stories about friendship, helping others, and the joy of life! Comics to color! From the beginning of the XX century, coloring books are a great way for children to spend their time! Not only young ones will raise their creativity, learn manual skills but also discover colors and shapes! It is also a good way to settle the nerves, calm down and relax for energetic kiddos! Complete experience In the Comics library, you’ll find 92 great illustrations and the possibility to create your comic book! Prologue Check how our adventures start! Play in space with the robot or discover how the princess from the faraway kingdom and her favorite alpacorn are spending their free time. Time for the Hero and the Robot Together with the boy and the robot, we’ll go on many adventures: we meet a dinosaur who likes candy, enjoy a sea trip, and try to save a playful cat. All that in many surprising places! My Friend, Alpacorn This time we will accompany a girl and her unusual friend - Alpacorn (half alpaca, half unicorn). We’ll travel to the land of sweets, into the deeps of the sea to become mermaids and play on the snow and even explore space! Drawing Without Borders Create what’s comes to your mind! You have 8 blank comics…' FROM games WHERE igdb_id = 186576 ON CONFLICT (game_id, language_code) DO NOTHING;
