INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('idle-ark-sail-and-build', 215417, '2021-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ee5.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Idle Ark: Sail and Build', 'Idle Arks: Sail and Build is a unique game where you are like in the movie "Waterworld" on your own one of the few ships in the world sailing in search of a new home. The player places blocks to build a ship, which must be placed correctly, so as not to collide with other ships and objects. You can build a mast, deck, sails, hull, rigging and rudder. Blocks can also be used to place cannons, anchors and even a submarine. To indicate in which direction to sail, you must place a flag. After placing all the blocks you can set sail by choosing the direction and speed. You can control the ship with the arrow keys. The up and down keys change the sails, and the keys left and right to change the rudder. The game will please and mini-game in which you can take part in a sea battle against enemy ships, shooting at them with guns. A bonus for destroying blocks will be the opportunity to win additional ships.' FROM games WHERE igdb_id = 215417 ON CONFLICT (game_id, language_code) DO NOTHING;
