INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garena Free Fire Max', 'Free Fire Max is designed exclusively to deliver premium gameplay experience in a Battle Royale. Enjoy a variety of exciting game modes with all Free Fire players via exclusive Firelink technology. Experience combat like never before with Ultra HD resolutions and breathtaking effects. Ambush, snipe, and survive; There is only one goal: to survive and be the last one standing.' FROM games WHERE igdb_id = 149972 ON CONFLICT (game_id, language_code) DO NOTHING;
