INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bolt Age', 'The Bolt Age is a dynamic action game, full of prodigious retro-futurist designs and shadowy creatures from another dimension. In story mode, the player will enjoy hours of fun with this 3d Cover Shooter. We will put ourselves in the shoes of William Bolt, an intelligent apprentice of science, Nikola Tesla''s pupil, but trained in the art of war with the purpose of stopping the announced invasion of inconceivable beings, coming from a dimension of death.' FROM games WHERE igdb_id = 165532 ON CONFLICT (game_id, language_code) DO NOTHING;
