INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gallic Wars: Battle Simulator', 'Gallic Wars is a Roguelike tactical strategy game. Fast gameplay, crazy rag-doll physics and challenging rouge-like approach to strategy. Fight your way through roman legions. DEPLOY your troops, PLAN their movement, use magic and items to give yourself an edge, and WIN. Features: - One of a kind approach to the strategy genre - Cartoony style - a true eye candy! - Fast gameplay - Powerful magic and mighty generals - Ragdoll physics - everyone likes ragdoll physics! - Easy to play, hard to master!' FROM games WHERE igdb_id = 146999 ON CONFLICT (game_id, language_code) DO NOTHING;
