INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drive Drift X', 'Enjoy this racing game that''s easy to pick up and fun for the whole family! Pass around the Joy-Con Controller and compete with up to four players! Featuring a variety of racing vehicles! Choose from cars, bikes, trucks, and even tanks! Transform a range of locations into your racecourse, from town streets to seasides! Find your perfect vehicle and go for your fastest time! Use drifts to take any turn with ease! Increase your speed by charging up boosts during drifts! Floor it and take first place!' FROM games WHERE igdb_id = 187487 ON CONFLICT (game_id, language_code) DO NOTHING;
