INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ni no Kuni: Cross Worlds', 'Ni no Kuni: Cross Worlds is an upcoming role-playing video game developed by Netmarble and published by Level-5. It will be released for Android and iOS in Japan in 2020, and will be created using the Unreal Engine 4 game engine. The game follows a beta tester for "Project N", a fictional virtual reality game. It will also include five character classes, and well as a multiplayer kingdom feature with player versus player combat.' FROM games WHERE igdb_id = 125759 ON CONFLICT (game_id, language_code) DO NOTHING;
