INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogues Adventure', 'Rogues Adventure is a puzzle platformer adventure game. Each level has a lot of coins, and there are obstacles that are destroyed when you collect the required amount of coins, and then you can go through the level further. Further on the levels, enemy characters appear, which, like obstacles, prevent your hero from advancing along the level. And also there are various traps and other things that can both interfere and help your character.' FROM games WHERE igdb_id = 155401 ON CONFLICT (game_id, language_code) DO NOTHING;
