INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('squabble', 151597, '2021-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3e8z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9hh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squabble', 'Choose your favourite sibling character and own others in-game. Attack your opponents or play defensively, use the environment to your advantage. Trap your opponents or just get rid of them in the old-fashioned way. Be mindful of your surrounding as the world around you changes and reveals its not-so-friendly face. You can play in a party of 4 players in the local multiplayer and fight for the ultimate victory. Game characters are children siblings fighting each other as they always do using any means necessary - exploding pillows, water guns, by unleashing monsters and also with the worst thing ever - their homework. The desire to win is great, following squabble is even greater. Let''s dive into atmosphere of pixel art couch playstyle. With your skill growing there comes even bigger passion for win. Explore vivid rooms, extremely dangerous and be ready to squabble!' FROM games WHERE igdb_id = 151597 ON CONFLICT (game_id, language_code) DO NOTHING;
