INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outbreak: The Nightmare Chronicles - Definitive Edition', 'Return to the world of survival horror. Monstrous beasts and disfigured remnants roam freely with their numbers increasing rapidly. Scattered and separated from your fellow survivors, you''ve fled into a large manor estate to escape the relentless horde. Your only goal now is survival. Explore the manor, locate supplies and find a way to wake from this nightmare. But somehow... you know your fate is sealed.' FROM games WHERE igdb_id = 164713 ON CONFLICT (game_id, language_code) DO NOTHING;
