INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gachi Dash', 'An exciting adventure through the most unusual places in Russia. Visit the places known to every person and feel the atmosphere of the fact that you need to escape from there as soon as possible. Run as fast as you can, but be careful, the exit path is not always straight, so you will have to avoid numerous obstacles! Try your luck in two game modes. Classic gameplay game known and understandable for every. Just jump and try not to die!' FROM games WHERE igdb_id = 180005 ON CONFLICT (game_id, language_code) DO NOTHING;
