INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Match Atlantis Solitaire 2', 'Return to the amazing undersea world of Atlantis Solitaire for a new adventure! Embark on a journey across more than 600 oceanic levels and restore 10 magnificent seascapes. Unravel 24 solitaire variants and enjoy 150 levels of a fully-featured Mahjong game. Take quests and unlock beautiful fish to populate the ocean. Solve the brand-new supersize and challenge levels as you explore wonderful Jewel Match Atlantis Solitaire 2.' FROM games WHERE igdb_id = 153397 ON CONFLICT (game_id, language_code) DO NOTHING;
