INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prodigal', 'After two years abroad, the prodigal childe of Tremere Elder Benedict finally returns.... but all is not well. Was this familiar mansion always so rotten? Was your daytime sleep always this troubled? Did these usual smiles always hide something? And why can''t you remember anything about this ''trip'' you''re supposed to have gone on?
