INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disaster Crisis', '《灾难危机》主要讲述外来生物人入侵地球，为解救快崩溃的世界，你将扮演幸存者、战士等角色，从安德烈亚斯城市开始，在冒险的旅程上解决阻止这场外来生物人入侵地球的大灾难。你将组建英雄的队伍，在地图上升级刷怪，购买搜刮最强武器装备，带领他们完成艰巨的任务，直到打倒最后的幕后敌人。' FROM games WHERE igdb_id = 166749 ON CONFLICT (game_id, language_code) DO NOTHING;
