INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not Another Advent Story', 'In the game, you will control the journey of MC as they try to make their way to church on Christmas Eve. You will run into a series of roadblocks and unexpected changes to your path. As you meet the cast of lonely characters, you will be given chances to make a connection, take action, or simply try to survive the night on your own.' FROM games WHERE igdb_id = 210496 ON CONFLICT (game_id, language_code) DO NOTHING;
