INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blow-up-monsters', 147568, '2021-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co573t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9s1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blow Up Monsters', 'Blow Up Monsters is an arcade, physics-based game where you need to use bombs to eliminate all monsters from the map. There are lots of levels to go through, and you need to test your prowess as you try to complete every level. The game is very immersive, and you always need to remove all the monsters, even if it feels hard to do. There are lots of dynamic elements that move in the game, so you can use those to your advantage. In the end, you must use the limited number of bombs to kill enemies and it will be well worth it every time. Blow Up Monsters has dozens of great levels and game worlds, and you have to use all the tools at your disposal to try and win as quickly as possible!' FROM games WHERE igdb_id = 147568 ON CONFLICT (game_id, language_code) DO NOTHING;
