INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chumlee''s Adventure: The Quest for Pinky', 'Chumlee''s Adventure: The Quest for Pinky is a brand new, authentic game created for the Nintendo Entertainment System. Taking inspiration from NES games of old, Chumlee''s Adventure: The Quest for Pinky is a platformer adventure game where you''ll face off against the friends you know and love from Pawn Stars, the hit TV show as seen on the History Channel. This game is an official release, incorporating their direct input and made in conjunction with the show''s stars and producers.' FROM games WHERE igdb_id = 142116 ON CONFLICT (game_id, language_code) DO NOTHING;
