INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzling Places', 'Puzzling Places brings relaxing and wholesome 3D jigsaw puzzling to VR. Put together hyper-realistic miniatures of beautiful places from around the globe. Enter the meditative flow of puzzling and enjoy each place coming alive with their unique & immersive soundscapes as you complete them.
