INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fate-of-the-pharaoh', 10316, '2021-05-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7gwf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc6o.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate of the Pharaoh', 'The greedy enemy wanted the treasures of Egypt. Long time attacks exhausted the magnificent realm of Pharaoh. Days of glory are far behind now, wrapped in dust of endless deserts. But, there''s hope! The enemy finally fled! Take the role of brave young Pharaoh''s adviser and raise the golden cities of Egypt once again in this fun and beautiful strategy/management game. Construct homes for your people, set-up production, trade, please gods, fight crocodiles and dangerous cobras while build monuments and famous wonders of Egyptian realm. And, be visited by aliens from space that will teach you secrets of how to build the mighty pyramids! All this, and much more in Fate of the Pharaoh!' FROM games WHERE igdb_id = 10316 ON CONFLICT (game_id, language_code) DO NOTHING;
