INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby Puzzle: First Learning Shapes for Toddlers', 'This puzzle game is extremely easy to use and was tailored with great care to be played by children of all ages, especially early childhood and pre-kindergarten age. It contains different difficulty-levels so it can grow with your toddler. Balloons and Bubbles can be popped at the end of each puzzle, adding extra fun to the game.' FROM games WHERE igdb_id = 147985 ON CONFLICT (game_id, language_code) DO NOTHING;
