INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ayuda-mystery-adventure', 174255, '2021-04-14', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ayuda: Mystery Adventure', 'Ayuda is a first person point and click graphic puzzle adventure, similar to games you may have played in the ’90’s. A simple gameplay interface consisting of the world that you explore and an inventory panel where you can collect, combine and use items you find along the way to solve puzzles. Explore areas, collect hidden objects and take in your surroundings. You will need all of your puzzle solving skills to put together a plan to make your way through the island, solving riddles and down the many paths towards the secret treasure of Ayuda. How you tackle the puzzles is down to you. Each puzzle has a logical solution, so take your time, there is no rush and enjoy the process of understanding what you have to do.' FROM games WHERE igdb_id = 174255 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 174255 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
