INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vine Worlds', 'The sequel to 2020''s Vine Realms, Vine Worlds is a 3D MMO-like collectathon based on the Vinesauce community. Inspired by walking simulators, embark on a journey by yourself (or up to 200 players on a server) through many worlds, unlock emotes based on the streamers, collect EXP by exploring or playing minigames to spend on cosmetics, and meet hundreds of characters with unique and humourous dialogue.' FROM games WHERE igdb_id = 165259 ON CONFLICT (game_id, language_code) DO NOTHING;
