INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quan-zhan-tian-xia', 156616, '2021-04-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ohe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwbr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '全战天下', '【穿越文明，征阀天下】 这是一款历时3年精心制作的跨时空大型多人在线地缘SLG游戏。力求给各位主公带来平衡、有趣、刺激的对抗体验。 我们不设置VIP特权，不出售资源和体力，也不提供类似高级迁城的功能，不设置行军付费加速功能，你可以通过攻城略地、民情任务、秘境闯关、联盟任务、纪元系统等玩法获取资源，公平对决，快速成长，真实体验策略博弈的魅力，感受波澜壮阔的乱世征途！ （本作品可免费下载，游戏内有内购，请诸位主宫充分体验后，适度支持）' FROM games WHERE igdb_id = 156616 ON CONFLICT (game_id, language_code) DO NOTHING;
