INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wallace-and-gromit-the-big-fix-up', 321331, '2021-01-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co94zc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuczo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wallace & Gromit: The Big Fix Up', 'Combining the latest in augmented and mixed reality, Wallace and Gromit: The Big Fix Up, is an all new epic adventure in which fans are able to experience and interact with the story as it unfolds over time. Join Wallace and his faithful hound as their latest business venture, Spick and Spanners, takes on the contract of a lifetime: to ''Fix Up'' Bristol. Download our free app and play along at home, as an employee, and for the first time ever, YOU can step directly into the wonderful world of Wallace and Gromit.' FROM games WHERE igdb_id = 321331 ON CONFLICT (game_id, language_code) DO NOTHING;
