INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fenrir''s Prelude', 'You play as Fenrir, living on a floating island named Midrealm. You have friends who you care about, including your best friends: Amaterasu and Aphrodite. But you get the idea that something is off with someone on the island, especially once Aphrodite goes missing. It is up to you to figure out what is happening on Midrealm.' FROM games WHERE igdb_id = 143510 ON CONFLICT (game_id, language_code) DO NOTHING;
