INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brave-cano', 174350, '2021-06-27', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brave Cano', 'A tale of a pretentious boy, growing up to become a true hero. A simple single-player action RPG that has everything you want. The countless cut-scenes make the game feel like an animated movie. Enjoy the story that unfolds as you progress through the stages! Most stages require decent dexterity, but you will face riddling stages along the way as well. But don’t worry, we believe you are more than capable of pushing through. Summon Roots to bind enemies who are running away. And when you encounter Shielded Enemies, try using poison! Find the optimal strategy for each stage. There’s an answer to every stage.' FROM games WHERE igdb_id = 174350 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 174350 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
