INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Fighter 5: Ultimate Showdown', 'The legendary fighting series returns with Virtua Fighter 5: Ultimate Showdown! Challenge the greatest fighters in the world in the ultimate remaster of the classic 3D fighter, now featuring gorgeous HD graphics, new online features, and all the bone-crunching, martial arts combat of the renowned original. Battle through classic VF modes like “Arcade” or “Rank Match,” create your own custom online tournaments with up to 16 friends, or learn from the best with the new “Spectator Mode.” Master your fighting style to defeat all challengers in the Fifth World Fighting Tournament and become a Virtua Fighter legend!' FROM games WHERE igdb_id = 148696 ON CONFLICT (game_id, language_code) DO NOTHING;
