INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-universe-puppies-and-kittens', 169236, '2021-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zdt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c9s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Universe: Puppies and Kittens', 'Whether you’re a dog or a cat person, your new companions are waiting for you to take them home and give them endless love. Help them grow daily with good care and proper training so they will become well behaved pets. Do not forget to give them lots of cuddles and play with them often. Each animal is unique and has its own personality and preferences so pay attention to your animal needs and they will give it back to you by becoming the most loyal of friends. You can even teach your pet tricks and train them to enter competitions and unlock rewards & new accessories. Participate also in various activities like exploring your neighborhood to find treasures, visiting the meadow and the dog park or go to the shop to acquire new items. Engage with other pets whist walking your companion so they can make four-legged friends to play with and get advice from other owners on how to raise your puppy well.' FROM games WHERE igdb_id = 169236 ON CONFLICT (game_id, language_code) DO NOTHING;
