INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shaped Touches', '''Shaped Touches'' is a simulation game of our future public spaces. Every 60 seconds, the game restarts in the same spaces with new sensory perceptions, experiencing the same place in new ways. This game was installed as part of the 17th International Architecture Exhibition - La Biennale di Venezia.' FROM games WHERE igdb_id = 154311 ON CONFLICT (game_id, language_code) DO NOTHING;
