INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('murder-diaries-3-santas-trail-of-blood', 186949, '2021-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5amg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cao.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder Diaries 3: Santa''s Trail of Blood', 'In this game you abstractly follow the narration of a young man who slowly but surely becomes insane. This leads you straight into the middle of an exciting murder case and a murder mystery unfolds while you listen to the testimonies of witness, friends and relatives. The whole game is somewhat Christmas flavored - however, don''t get yourself comfortable, the game not going to give you a nice and warm feeling but rather confront you with a cold and harsh reality as the thrilling storytelling of the game will leave you with a cold shiver down your spine. The game is a must have for any true fan of thrillers and anyone how enjoys a murder mystery that goes beyond the normal story telling. How does the gameplay work? You will play as a free-floating ghost like creature. Basically, as the soul of someone who is experiencing the story. You are very small in comparison to the surroundings and can fly freely through the area. You start by exploring the area and enjoying the feeling of flying as well as the gentle yet mysterious background music. Soon after starting to explore, you will find the first memory piece. You can collect the memory pieces to continue with the story and to advance with the overall narration. The story talks about a young boy, about his live and about how everything changes. It is setup as a thrilling murder mystery and acts as a contrast to the somewhat calm and enjoyable gameplay.' FROM games WHERE igdb_id = 186949 ON CONFLICT (game_id, language_code) DO NOTHING;
