INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('akibas-trip-hellbound-and-debriefed', 119460, '2021-05-19', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fc7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar96s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akiba''s Trip: Hellbound & Debriefed', 'Akiba''s Trip: Hellbound & Debriefed is the precursor to Akiba''s Trip: Undead & Undressed, the smash hit that introduced a Western audience to the seedy underworld lurking in the shadows of the haven of “otaku” culture in the Akihabara district of Tokyo. Released as Akiba''s Trip Plus in Japan, players explore an accurately modeled recreation of the famous “Akiba” district circa 2012, hunting vampiric foes, and tearing off their clothes to expose them to sunlight. The game has been remade to bring it to modern HD graphical standards, all while retaining the charm of the original classic that started a cult hit series.' FROM games WHERE igdb_id = 119460 ON CONFLICT (game_id, language_code) DO NOTHING;
