INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mombo Quest', 'Super Mombo Quest is an action-packed precision platformer! A metroidvania with classic arcade mechanics, featuring some crazy combat, challenging combos and plenty of collectibles - all in a huge interconnected world! Bounce and stomp through an enormous interconnected world, doing some intense acrobatics and getting huge combos! A superfast precision platformer that mixes up a Metroidvania world with classic Arcade mechanics.' FROM games WHERE igdb_id = 139438 ON CONFLICT (game_id, language_code) DO NOTHING;
