INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Prince of Landis', 'In the year 198X, young Evan must survive a bleak life in the snowy backwater of Landis, Oregon. One fateful day, his existence is forever changed by the dark influences of a strange visitor from another world. With the guidance of his new ally, can Evan stand up against schoolyard bullies? Will he have the courage to stand up for himself? The Prince of Landis combines the character-driven story and dialog of a visual novel with the exploration and puzzle-solving of an adventure game.' FROM games WHERE igdb_id = 178791 ON CONFLICT (game_id, language_code) DO NOTHING;
