INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloodrayne: Revamped', 'Enhanced and updated for modern consoles, this is the definitive edition of BloodRayne. In this frenetic and bloody third-person shooter that unleashed the iconic red-headed femme fatale on the world, the dhampir Rayne battles horrific creatures and hordes of soldiers with an array of vampric abilities and powerful weapons. Acrobatically slash and shoot your way through the swamps of Louisiana, the cavernous depths of a mining operation in Argentina, and a ruinous German castle. Experience the origins of Rayne through her first missions for the Brimstone Society in this improved version of the horror-action classic.' FROM games WHERE igdb_id = 178176 ON CONFLICT (game_id, language_code) DO NOTHING;
