INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboSquare', 'Jump into speedy hazard-packed Robo battles with up to 15 other players where random series of synchronized events destroy the fighting arena. Everyone zooms around the level bumping, drifting, and flipping to become the ultimate winner by being the last one to standing in an ongoing stage of madness. Join a sumo-inspired experience with a rush of energetic motor buzz where even the hardest hits and coolest tricks might not save you from the mayhem on the screen.' FROM games WHERE igdb_id = 141205 ON CONFLICT (game_id, language_code) DO NOTHING;
