INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Soccer Blast: America VS Europe', 'Super Soccer Blast America vs Europe is an arcade-style football game that tackles football in a light-hearted and accessible way. As a breakaway from the seriousness of simulation and realism, it brings a very arcade style to the field with retro throwbacks. Prepare for the kick-off with a fast-paced football game, bringing a refreshing look to the football genre with accessible controls and skilled-based gameplay like over-the-top classic soccer games.' FROM games WHERE igdb_id = 152520 ON CONFLICT (game_id, language_code) DO NOTHING;
