INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wanderlust: The Bermuda Secret - Collector''s Edition', 'After your flight takes you into an ominous cloud bank, you soon find yourself hidden within the eye of a permanent storm at the center of the Bermuda Triangle, with no connection to the rest of the world, no supplies, and no hope of escape from a strange island! This point and click, puzzle adventure tasks players with finding a list of objects hidden, to uncover the truth of the island.
