INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('our-battle-has-just-begun-episode-1', 154242, '2021-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3qpb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arux9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Our Battle Has Just Begun! episode 1', 'You have no memory of your adventure or heroic strength, and yet the people celebrate you as the Hero who saved the realm. This is just your typical adventure game filled with heroes and heroines...except it starts where games usually end. In the midst of an unconscious state, you hear a voice desperately calling out to you. ""....ster...ro... Master Hero!"" That''s when you wake up and see... the Demon King cursing you as he vanishes into thin air! ""...Huh? Is this for real?! But I''m way too late! The Demon Lord was already defeated when I got here!"" And so you become the Hero destined to save the realm. At the very moment you deal a deadly blow to the Demon Lord, your memories of your previous life come flowing back. And thus, the heroic group decides to return to their homeland. Each country you stop in along the way welcomes you with open arms as the Hero who saved the realm. It seems like you have it made, but maybe it really is too good to be true. The real battle is only getting started!' FROM games WHERE igdb_id = 154242 ON CONFLICT (game_id, language_code) DO NOTHING;
