INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MekaFighters', 'MekaFighters is a futuristic world where Mechs(Mekas) are the highest grade weapons humanity has ever come across and countries clash against others in wars to maintain dominance in the world. Battle out against other players and emerge victorious outplaying and skillfully using your abilities to defend, attack, and destroy enemy mekas.' FROM games WHERE igdb_id = 146350 ON CONFLICT (game_id, language_code) DO NOTHING;
