INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umineko no Naku Koro ni: Gisho no.XXX', 'An extra arc originally included in Umineko no Naku Koro ni Hane where Battler Ushiromiya returns to Rokkenjima after a six-year absence, but instead of having a friendly reunion with his family, he has plans of murder. This episode explores darker themes and diverges from the canonical timeline, offering fans a speculative “what-if” story.' FROM games WHERE igdb_id = 272517 ON CONFLICT (game_id, language_code) DO NOTHING;
