INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ultimate Game', 'The Ultimate Game is a fast paced sport played 2v2 up to 7v7. The game is about passing the disc - realistic flight physics and intricate thrower controls allow for a huge variety in flight paths. Everyone but the current thrower can run and jump freely. Points are scored by catching the disc in endzone.' FROM games WHERE igdb_id = 143818 ON CONFLICT (game_id, language_code) DO NOTHING;
