INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aery-calm-mind', 153831, '2021-05-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3glg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru2x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aery: Calm Mind', 'Aery: Calm Mind is an interactive game experience that is designed to relax your mind and soul. You jump into the role of a little bird, explore beautiful landscapes and collect the missing feathers of your little bird friend. Because there are no enemies or any danger of any kind you will be able to lean back and enjoy the scenery and the sensation of flying. It is a great game for relaxing and calming down after an exhausting day full of hassle. Every level has two parts. A first introduction into the overall theme and a second one that gives a little more time to play around and to enjoy the beauty of the area. Of course, you can always select the level that you feel helps most to relax yourself. Most levels can be finished quite quickly so that you can freely choose spend time exploring the environment but you don’t have to stay for too long if you are just looking for a short moment of peace and enjoyment.' FROM games WHERE igdb_id = 153831 ON CONFLICT (game_id, language_code) DO NOTHING;
