INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faircroft''s Antiques: The Heir of Glen Kinnoch', 'Mia Faircroft’s adventures continue in The Heir of Glen Kinnoch! In this classic Hidden Object Game, search through bright and beautiful locations, restore priceless antiques in exciting minigames, and uncover who will inherit Castle MacDougal.' FROM games WHERE igdb_id = 148993 ON CONFLICT (game_id, language_code) DO NOTHING;
