INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy: Sky Warriors', 'An interesting twist on the background history of the original Final Fantasy! This game feature what happened 200 years before the original Final Fantasy 1 for the NES, featuring an unexpected cast of characters otherwise known as the ''Sky Warriors'' in the canon game. Witness the catastrophe of the four Fiends of Elements making their grand entrance into the Final Fantasy world, and experience the Lufenian response!' FROM games WHERE igdb_id = 262006 ON CONFLICT (game_id, language_code) DO NOTHING;
