INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero''s Hour', 'Hero''s Hour is a game inspired by the Heroes of Might and Magic turnbased strategy games. "Hour" refers to the more fast-paced gameplay, with combat taking place on a real-time simulated battlefield. You may just watch the battle as a casual player, or take control of your units as desired.' FROM games WHERE igdb_id = 145822 ON CONFLICT (game_id, language_code) DO NOTHING;
