INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Your Voice in the Autumn Leaves', 'After his girlfriend Kaori broke up with him, 17 year old student Kure isolated himself from the world, spending his time home, heartbroken, listening to sad indie songs and playing videogames. Then, one day, outside the Hospital where his mother works, Kure met someone very special: a girl named Autumn, who has been diagnosed with cancer and is trying to assimilate her situation. That day would change their lives forever...' FROM games WHERE igdb_id = 225819 ON CONFLICT (game_id, language_code) DO NOTHING;
