INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('can-androids-survive', 167709, '2021-09-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7gnw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1b7y.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can Androids Survive', 'Becoming a walking, 2-ton supply line in a new shortform sandbox mech FPS from the writer of Can Androids Pray. In Can Androids Survive, you are a battlefield courier, sent to an active warzone on the Moon to deliver supplies to Starbound Alliance bases--even if it costs your life in the process. Battle a draining fuel gauge, hordes of mechanized hazards, and a treacherous lunar surface to unravel the nature of your existence. Jettison fuel through your exhaust ports to escape stellar float mines and launch your chassis across craters. End the war itself--by destroying the field.
