INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Addams Family: Mansion Mayhem', 'Only you and your friends can help Wednesday, Pugsley, Gomez, and Morticia save the Addams Family Mansion in this horrifyingly hilarious 3D adventure for up to four players. The mansion is full of spooky scares – but can you discover its hair-raising secrets and save it from an unexpected threat? Use each iconic character''s abilities to explore the house, solve puzzles, and find lost relics. Play competitive minigames that will have you bumping and jumping over each other to win.' FROM games WHERE igdb_id = 150006 ON CONFLICT (game_id, language_code) DO NOTHING;
