INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totemlands', 'You are an adventurer who just arrived at the mysterious land of Oakshade, inhabited by spirits known as Oaklingers, peculiar locals and… totems? Totemlands is a relaxing crafting, building game where you hunt spirits, use them to craft and raise totem poles. Totem poles produce valuable resources called Relics, which can be sold for Golden Acorns (in-game currency). which later can be used to expand, upgrade or unlock new territories.' FROM games WHERE igdb_id = 213941 ON CONFLICT (game_id, language_code) DO NOTHING;
