INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feral Flowers', 'Feral Flowers is a quick-fire roguelite platformer for hay fever haters: dodge the pollen, beat the flowers! Rather than a traditional health meter, the game''s timer needs to be topped up by killing enemies. The player can tank any number of hits - unless the timer reaches zero, in which case bullet hell ensues, and a single hit will send them all the way back to the first stage.' FROM games WHERE igdb_id = 182323 ON CONFLICT (game_id, language_code) DO NOTHING;
