INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dememorize', 'Dememorize is a 2.5D exploration horror game about N9, a degenerative, neurological disease that eats away at memory and spreads through eye contact. The gameplay is under an hour and mostly involves talking to other ward residents during the day in 3rd person, and then exploring the greater hospital by night in 1st person.' FROM games WHERE igdb_id = 191986 ON CONFLICT (game_id, language_code) DO NOTHING;
